draw(O--(1/sqrt(2),1/sqrt(2),0));
draw(O--(1/sqrt(2),-1/sqrt(2),0));
draw(A..(sqrt(15)/5,0,sqrt(10)/5)..B,red);
draw(A--B);
draw(O--C);

label("$x$", (1.2,0,0), SW);
label("$y$", (0,1.2,0), E);
label("$z$", (0,0,1.2), N);
